fn can_deduplicate_values(
    a: Option<&ComputedRegisteredValue>,
    b: Option<&ComputedRegisteredValue>,
) -> bool {
    match (a, b) {
        (Some(a), Some(b)) => {
            // TODO(emilio): Seems we should compare `url_data` as well? It doesn't seem to matter
            // much in practice since url values would be already-computed against the right base
            // URI here, I think...
            a == b && a.attr_tainted == b.attr_tainted
        },
        (None, None) => true,
        _ => false,
    }
}

impl PartialEq for Inner {
    fn eq(&self, other: &Self) -> bool {
        if self.len != other.len {
            return false;
        }
        // NOTE(emilio): In order to speed up custom property comparison when tons of custom
        // properties are involved, we return false in some cases where the ordering might be
        // different, but the computed values end up being the same.
        //
        // This is a performance trade-off, on the assumption that if the ordering is different,
        // there's likely a different value as well, but might over-invalidate.
        //
        // Doing the slow thing (checking all the keys) shows up a lot in profiles, see bug 1926423.
        //
        // Note that self.own_properties != other.own_properties is not the same, as by default
        // IndexMap comparison is not order-aware.
        //
        // Note also that for this comparison we do care about e.g. attribute-tainting being
        // different.
        {
            let own = self.own_properties.as_slice();
            let other = other.own_properties.as_slice();
            if own.len() != other.len() {
                return false;
            }
            for ((own_k, own_v), (other_k, other_v)) in own.iter().zip(other.iter()) {
                if own_k != other_k || !can_deduplicate_values(own_v.as_ref(), other_v.as_ref()) {
                    return false;
                }
            }
        }
        self.parent == other.parent
    }
}

fn get(&self, name: &Name) -> Option<&ComputedRegisteredValue> {
    if let Some(p) = self.own_properties.get(name) {
        return p.as_ref();
    }
    self.parent.as_ref()?.get(name)
}

fn do_insert(&mut self, name: &Name, value: Option<ComputedRegisteredValue>) {
    if let Some(inner) = Arc::get_mut(&mut self.0) {
        return inner.insert(name, value);
    }
    if self.get(name) == value.as_ref() {
        return;
    }
    if !self.0.should_expand_chain() {
        return Arc::make_mut(&mut self.0).insert(name, value);
    }
    let len = self.0.len;
    let ancestor_count = self.0.ancestor_count + 1;
    let mut new_inner = Inner {
        own_properties: Default::default(),
        // FIXME: Would be nice to avoid this clone.
        parent: Some(self.0.clone()),
        len,
        ancestor_count,
    };
    new_inner.insert(name, value);
    self.0 = Arc::new(new_inner);
}

pub fn insert(&mut self, name: &Name, value: ComputedRegisteredValue) {
    self.do_insert(name, Some(value))
}

pub fn remove(&mut self, name: &Name) {
    self.do_insert(name, None)
}

fn init_custom_properties(&mut self, context: &mut computed::Context) {
    let is_root_element = context.is_root_element();
    let initial_values = self.stylist.get_custom_property_initial_values();
    let inherited = if is_root_element {
        debug_assert!(context.inherited_custom_properties().is_empty());
        initial_values.inherited.clone()
    } else {
        context.inherited_custom_properties().inherited.clone()
    };
    let properties = ComputedCustomProperties {
        inherited,
        non_inherited: initial_values.non_inherited.clone(),
    };
    context.builder.substitution_functions =
        ComputedSubstitutionFunctions::new(Some(properties), None);
}

fn cascade_custom_property(
    &mut self,
    context: &mut computed::Context,
    declaration: &'a CustomDeclaration,
    priority: CascadePriority,
) {
    let CustomDeclaration {
        ref name,
        ref value,
    } = *declaration;

    if let Some(reverted) = self.reverted.custom.get(name)
        && !reverted.allows(&priority)
    {
        return;
    }

    if !(priority.flags() - context.included_cascade_flags).is_empty() {
        return;
    }

    let entry = match self.seen.custom.var.entry(name) {
        Entry::Occupied(..) => return,
        Entry::Vacant(v) => v,
    };

    let registration = self.stylist.get_custom_property_registration(name);
    let initial_values = self.stylist.get_custom_property_initial_values();
    if !Self::value_may_affect_style(context, name, registration, initial_values, value) {
        entry.insert(false);
        return;
    }

    let has_references = match value {
        CustomDeclarationValue::Unparsed(unparsed_value) => {
            // Non-custom dependency is really relevant for registered custom properties
            // that require computed value of such dependencies.
            unparsed_value
                .references
                .flags
                .intersects(ReferenceFlags::ATTR | ReferenceFlags::VAR)
                || !find_non_custom_references(
                    registration,
                    unparsed_value,
                    context.is_root_element(),
                )
                .is_empty()
        },
        // XXX This matches the previous behavior but I don't think it's fully sound. Parsed
        // values may have non-custom references, can't they? But also how do we get a parsed
        // value at all here?
        CustomDeclarationValue::Parsed(..) => false,
        // If we're a wide keyword we either get an initial value or an inherited one (no
        // references). Revert might have references, but we remove the `seen` entry, so it
        // doesn't matter.
        CustomDeclarationValue::CSSWideKeyword(..) => false,
    };
    self.may_have_custom_property_cycles |= has_references;
    entry.insert(has_references);

    match value {
        CustomDeclarationValue::Unparsed(unparsed_value) => {
            if !has_references {
                // If the variable value has no references to other properties, perform
                // substitution here instead of forcing a full traversal in `substitute_all`
                // afterwards.
                substitute_references_if_needed_and_apply(
                    name,
                    None,
                    unparsed_value,
                    self.stylist,
                    context,
                    // We just checked there are no attr dependencies.
                    &mut AttributeTracker::new_dummy(),
                );
                return;
            }
            let value = ComputedRegisteredValue::universal(Arc::clone(unparsed_value));
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        CustomDeclarationValue::Parsed(parsed_value) => {
            let value = parsed_value.to_computed_value(context);
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        CustomDeclarationValue::CSSWideKeyword(keyword) => match keyword.revert_kind() {
            Some(revert_kind) => {
                self.seen.custom.var.remove(name);
                if revert_kind != RevertKind::Rule {
                    self.reverted
                        .custom
                        .entry(name.clone())
                        .or_default()
                        .add(priority, revert_kind);
                }
            },
            None => match keyword {
                CSSWideKeyword::Initial => {
                    // For non-inherited custom properties, 'initial' was handled in value_may_affect_style.
                    debug_assert!(registration.inherits(), "Should've been handled earlier");
                    remove_and_insert_initial_value(
                        name,
                        registration,
                        initial_values,
                        &mut context.builder.substitution_functions,
                    );
                },
                CSSWideKeyword::Inherit => {
                    // For inherited custom properties, 'inherit' was handled in value_may_affect_style.
                    debug_assert!(!registration.inherits(), "Should've been handled earlier");
                    context
                        .style()
                        .add_flags(ComputedValueFlags::INHERITS_RESET_STYLE);
                    let inherited_value = context
                        .inherited_custom_properties()
                        .non_inherited
                        .get(name)
                        .cloned();
                    if let Some(inherited_value) = inherited_value {
                        context.builder.substitution_functions.insert_var(
                            registration,
                            name,
                            inherited_value,
                        );
                    } else {
                        context
                            .builder
                            .substitution_functions
                            .remove_var(registration, name);
                    }
                },
                // handled in value_may_affect_style or in the revert_kind branch above.
                CSSWideKeyword::Revert
                | CSSWideKeyword::RevertLayer
                | CSSWideKeyword::RevertRule
                | CSSWideKeyword::Unset => unreachable!(),
            },
        },
    }
}

fn value_may_affect_style(
    context: &computed::Context,
    name: &Name,
    registration: &PropertyDescriptors,
    initial_values: &ComputedCustomProperties,
    value: &CustomDeclarationValue,
) -> bool {
    match *value {
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Inherit) => {
            // For inherited custom properties, explicit 'inherit' means we
            // can just use any existing value in the inherited
            // CustomPropertiesMap.
            if registration.inherits() {
                return false;
            }
        },
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Initial) => {
            // For non-inherited custom properties, explicit 'initial' means
            // we can just use any initial value in the registration.
            if !registration.inherits() {
                return false;
            }
        },
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Unset) => {
            // Explicit 'unset' means we can either just use any existing
            // value in the inherited CustomPropertiesMap or the initial
            // value in the registration.
            return false;
        },
        _ => {},
    }

    let existing_value = context
        .builder
        .substitution_functions
        .get_var(registration, name);
    let Some(existing_value) = existing_value else {
        if matches!(
            value,
            CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Initial)
        ) {
            debug_assert!(registration.inherits(), "Should've been handled earlier");
            // The initial value of a custom property without a
            // guaranteed-invalid initial value is the same as it
            // not existing in the map.
            if registration.initial_value.is_none() {
                return false;
            }
        }
        return true;
    };
    match value {
        CustomDeclarationValue::Unparsed(value) => {
            // Don't bother overwriting an existing value with the same
            // specified value.
            if let Some(existing_value) = existing_value.as_universal() {
                return existing_value != value;
            }
        },
        CustomDeclarationValue::Parsed(..) => {
            // If the value has dependencies, context might not yield the same
            // result as the eventual value.
        },
        CustomDeclarationValue::CSSWideKeyword(kw) => {
            match kw {
                CSSWideKeyword::Inherit => {
                    debug_assert!(!registration.inherits(), "Should've been handled earlier");
                    // Root inheritance uses the already-seeded initial value.
                    if context.is_root_element() {
                        return false;
                    }
                },
                CSSWideKeyword::Initial => {
                    debug_assert!(registration.inherits(), "Should've been handled earlier");
                    // Don't bother overwriting an existing value with the initial value
                    // specified in the registration.
                    if let Some(initial_value) = initial_values.get(registration, name) {
                        return existing_value.attr_tainted || existing_value != initial_value;
                    }
                },
                CSSWideKeyword::Unset => {
                    debug_assert!(false, "Should've been handled earlier");
                },
                CSSWideKeyword::Revert
                | CSSWideKeyword::RevertLayer
                | CSSWideKeyword::RevertRule => {},
            }
        },
    };

    true
}

impl PartialEq for VariableValue {
    fn eq(&self, other: &Self) -> bool {
        self.css == other.css
    }
}

fn map_mut(&mut self, registration: &PropertyDescriptors) -> &mut CustomPropertiesMap {
    if registration.inherits() {
        &mut self.inherited
    } else {
        &mut self.non_inherited
    }
}

pub(crate) fn insert_var(
    &mut self,
    registration: &PropertyDescriptors,
    name: &Name,
    value: ComputedRegisteredValue,
) {
    self.custom_properties.insert(registration, name, value);
}

pub fn is_attr_tainted(&self) -> bool {
    self.references.flags.intersects(ReferenceFlags::ATTR) | self.explicitly_attr_tainted
}

pub fn substitute_references_if_needed_and_apply(
    name: &Name,
    namespace: Option<&Namespace>,
    value: &Arc<VariableValue>,
    stylist: &Stylist,
    context: &mut computed::Context,
    attribute_tracker: &mut AttributeTracker,
) {
    let is_var = namespace.is_none();
    let registration = stylist.get_custom_property_registration(name);
    if is_var && !value.has_references() && registration.is_universal() {
        // Trivial path: no references and no need to compute the value, just apply it directly.
        let computed_value = ComputedRegisteredValue::universal(Arc::clone(value));
        context
            .builder
            .substitution_functions
            .insert_var(registration, name, computed_value);
        return;
    }

    let url_data = &value.url_data;
    let substitution = substitute_internal(
        value,
        Some(PropertyIdRef::from(name)),
        &context.builder.substitution_functions,
        stylist,
        context,
        attribute_tracker,
        &mut SmallVec::new(),
        None,
    );

    let Ok(substitution) = substitution else {
        if is_var {
            handle_invalid_at_computed_value_time(name, registration, context);
        } else if let Some(namespace) = namespace {
            context
                .builder
                .substitution_functions
                .remove_attr(name, namespace);
        }
        return;
    };

    // If variable fallback results in a wide keyword, deal with it now.
    let inherited = context.builder.inherited_style.custom_properties();
    if is_var {
        let css = &substitution.css;
        let css_wide_kw = {
            let mut input = Parser::new(css);
            input.try_parse(CSSWideKeyword::parse)
        };

        if let Ok(kw) = css_wide_kw {
            // TODO: It's unclear what this should do for revert / revert-layer, see
            // https://github.com/w3c/csswg-drafts/issues/9131. For now treating as unset
            // seems fine?
            match (kw, registration.inherits(), context.is_root_element()) {
                (CSSWideKeyword::Initial, _, _)
                | (CSSWideKeyword::Revert, false, _)
                | (CSSWideKeyword::RevertLayer, false, _)
                | (CSSWideKeyword::RevertRule, false, _)
                | (CSSWideKeyword::Unset, false, _)
                | (CSSWideKeyword::Revert, true, true)
                | (CSSWideKeyword::RevertLayer, true, true)
                | (CSSWideKeyword::RevertRule, true, true)
                | (CSSWideKeyword::Unset, true, true)
                | (CSSWideKeyword::Inherit, _, true) => {
                    remove_and_insert_initial_value(
                        name,
                        registration,
                        stylist.get_custom_property_initial_values(),
                        &mut context.builder.substitution_functions,
                    );
                },
                (CSSWideKeyword::Revert, true, false)
                | (CSSWideKeyword::RevertLayer, true, false)
                | (CSSWideKeyword::RevertRule, true, false)
                | (CSSWideKeyword::Inherit, _, false)
                | (CSSWideKeyword::Unset, true, false) => {
                    if !registration.inherits() {
                        context
                            .style()
                            .add_flags(ComputedValueFlags::INHERITS_RESET_STYLE);
                    }
                    match inherited.get(registration, name) {
                        Some(value) => {
                            context.builder.substitution_functions.insert_var(
                                registration,
                                name,
                                value.clone(),
                            );
                        },
                        None => {
                            context
                                .builder
                                .substitution_functions
                                .remove_var(registration, name);
                        },
                    };
                },
            }
            return;
        }
    }

    match namespace {
        None => {
            let value = match substitution.into_value(
                url_data,
                registration,
                context,
                Some(PropertyIdRef::from(name)),
            ) {
                Ok(v) => v,
                Err(()) => {
                    handle_invalid_at_computed_value_time(name, registration, context);
                    return;
                },
            };
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        Some(namespace) => {
            let mut value =
                ComputedRegisteredValue::universal(Arc::new(VariableValue::new_resolved(
                    substitution.css.into_owned(),
                    url_data,
                    substitution.first_token_type,
                    substitution.last_token_type,
                )));
            value.attr_tainted |= substitution.attr_tainted;
            context
                .builder
                .substitution_functions
                .insert_attr(name, namespace, value);
        },
    }
}

fn into_value(
    self,
    url_data: &UrlExtraData,
    registration: &PropertyDescriptors,
    computed_context: &computed::Context,
    property_id: Option<PropertyIdRef>,
) -> Result<ComputedRegisteredValue, ()> {
    if registration.is_universal() {
        let mut value =
            ComputedRegisteredValue::universal(Arc::new(VariableValue::new_resolved(
                self.css.into_owned(),
                url_data,
                self.first_token_type,
                self.last_token_type,
            )));
        value.attr_tainted |= self.attr_tainted;
        return Ok(value);
    }
    let taint = if self.attr_tainted {
        // Per spec: substitution value of an arbitrary substitution function is
        // attr()-tainted as a whole if any attr()-tainted values were involved
        // in creating that substitution value.
        // https://drafts.csswg.org/css-values-5/#attr-security
        AttrTaint::new_fully_tainted(self.css.len())
    } else {
        AttrTaint::default()
    };
    let mut v = compute_value(
        &self.css,
        url_data,
        registration,
        computed_context,
        taint,
        property_id,
    )?;
    v.attr_tainted |= self.attr_tainted;
    Ok(v)
}

fn do_substitute_chunk<'a>(
    css: &'a str,
    start: usize,
    end: usize,
    first_token_type: TokenSerializationType,
    last_token_type: TokenSerializationType,
    url_data: &UrlExtraData,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    references: &'a [SubstitutionFunctionReference],
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SmallVec<[&'a Name; 8]>,
    mut attr_taint: Option<&mut AttrTaint>,
) -> Result<Substitution<'a>, ()> {
    if start == end {
        // Empty string. Easy.
        return Ok(Substitution::default());
    }
    // Easy case: no references involved.
    if references.is_empty() {
        let result = &css[start..end];
        return Ok(Substitution::new(
            Cow::Borrowed(result),
            first_token_type,
            last_token_type,
            Default::default(),
        ));
    }

    let mut substituted = ComputedValue::empty(url_data);
    let mut next_token_type = first_token_type;
    let mut cur_pos = start;
    let mut attr_tainted = false;
    let references = references.iter();
    for reference in references {
        if reference.start != cur_pos {
            substituted.push(
                &css[cur_pos..reference.start],
                next_token_type,
                reference.prev_token_type,
                /* attr_taint */ None,
            )?;
        }

        let substitution = substitute_one_reference(
            css,
            url_data,
            property_id,
            substitution_functions,
            reference,
            stylist,
            computed_context,
            attribute_tracker,
            seen,
        )?;

        // Optimize the property: var(--...) case to avoid allocating at all.
        if reference.start == start && reference.end == end {
            if let Some(taint) = attr_taint.filter(|_| substitution.attr_tainted) {
                taint.push(start, substitution.css.len());
            }
            return Ok(substitution);
        }

        substituted.push(
            &substitution.css,
            substitution.first_token_type,
            substitution.last_token_type,
            attr_taint
                .as_deref_mut()
                .filter(|_| substitution.attr_tainted),
        )?;
        attr_tainted |= substitution.attr_tainted;
        next_token_type = reference.next_token_type;
        cur_pos = reference.end;
    }
    // Push the rest of the value if needed.
    if cur_pos != end {
        substituted.push(
            &css[cur_pos..end],
            next_token_type,
            last_token_type,
            /* attr_taint */ None,
        )?;
    }
    Ok(Substitution::from_value(substituted, attr_tainted))
}

fn substitute_one_reference<'a>(
    css: &'a str,
    url_data: &UrlExtraData,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    reference: &'a SubstitutionFunctionReference,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SmallVec<[&'a Name; 8]>,
) -> Result<Substitution<'a>, ()> {
    let simple_attr_subst = |s: &str| {
        Some(Substitution::new(
            Cow::Owned(quoted_css_string(s)),
            TokenSerializationType::Nothing,
            TokenSerializationType::Nothing,
            /* attr_tainted */ true,
        ))
    };
    let substitution: Option<_> = match reference.substitution_kind {
        SubstitutionFunctionKind::Var => {
            let registration = stylist.get_custom_property_registration(&reference.name);
            match substitution_functions.get_var(registration, &reference.name) {
                None => None,
                // If the referenced value is itself still unresolved (i.e. it has references), we
                // are substituting against a partially-resolved map -- this happens while applying
                // a prioritary property in the middle of custom-property resolution. Resolve it
                // recursively, guarding against cycles (which the resolver will also remove, but it
                // may not have gotten to this variable yet).
                Some(v) => match v.as_universal() {
                    Some(u) if u.has_references() => {
                        if seen.contains(&&reference.name) {
                            // Cycle: the primary is guaranteed-invalid, so fall through to the
                            // fallback (if any), like any other invalid primary.
                            None
                        } else {
                            seen.push(&reference.name);
                            let result = substitute_internal(
                                u,
                                property_id,
                                substitution_functions,
                                stylist,
                                computed_context,
                                attribute_tracker,
                                seen,
                                /* attr_taint */ None,
                            );
                            seen.pop();
                            match result {
                                Ok(mut substitution) => {
                                    substitution.attr_tainted |= v.attr_tainted;
                                    Some(substitution)
                                },
                                // The primary couldn't be resolved (invalid); use the fallback.
                                Err(()) => None,
                            }
                        }
                    },
                    _ => Some(Substitution::from_value(
                        v.to_variable_value(),
                        v.attr_tainted,
                    )),
                },
            }
        },
        SubstitutionFunctionKind::Env => {
            let device = stylist.device();
            device
                .environment()
                .get(&reference.name, device, url_data)
                .map(|v| Substitution::from_value(v, /* attr_tainted */ false))
        },
        // https://drafts.csswg.org/css-values-5/#attr-substitution
        SubstitutionFunctionKind::Attr => {
            let namespace = match reference.attribute_data.namespace {
                ParsedNamespace::Known(ref ns) => Some(ns),
                ParsedNamespace::Unknown => None,
            };
            namespace
                .and_then(|namespace| {
                    LocalName::with_name(&reference.name, |local_name| {
                        attribute_tracker.query(local_name, namespace)
                    })
                })
                .map_or_else(
                    || {
                        // Special case when fallback and <attr-type> are omitted.
                        // See FAILURE: https://drafts.csswg.org/css-values-5/#attr-substitution
                        if reference.fallback.is_none()
                            && reference.attribute_data.kind == AttributeType::None
                        {
                            simple_attr_subst("")
                        } else {
                            None
                        }
                    },
                    |attr| {
                        let attr = if let AttributeType::Type(_) = &reference.attribute_data.kind {
                            // If we're evaluating a container query, we haven't run the cascade
                            // and populated substitution_functions.attributes, so we can't do the
                            // get_attr() lookup here.
                            // TODO: This means chained attr() references will not work reliably in
                            // container style queries:
                            // https://bugzilla.mozilla.org/show_bug.cgi?id=2028861
                            if computed_context.in_container_query {
                                attr
                            } else {
                                substitution_functions
                                    .get_attr(&reference.name, namespace?)
                                    .map(|v| v.to_variable_value())?
                                    .css
                            }
                        } else {
                            attr
                        };
                        let mut parser = Parser::new(&attr);
                        match &reference.attribute_data.kind {
                            AttributeType::Unit(unit) => {
                                let css = {
                                    // Verify that attribute data is a <number-token>.
                                    parser.skip_whitespace();
                                    let start = parser.position();
                                    parser.expect_number().ok()?;
                                    let mut s = String::from(parser.slice_from(start));
                                    parser.expect_exhausted().ok()?;
                                    s.push_str(unit.as_ref());
                                    s
                                };
                                let serialization = match unit {
                                    AttrUnit::Number => TokenSerializationType::Number,
                                    AttrUnit::Percentage => TokenSerializationType::Percentage,
                                    _ => TokenSerializationType::Dimension,
                                };
                                let value =
                                    ComputedValue::new(css, url_data, serialization, serialization);
                                Some(Substitution::from_value(
                                    value, /* attr_tainted */ true,
                                ))
                            },
                            AttributeType::Type(_) => {
                                let value = reference
                                    .attribute_data
                                    .parse_typed_value(&mut parser, url_data, property_id)
                                    .ok()?;
                                let value = value.to_variable_value();
                                Some(Substitution::from_value(
                                    value, /* attr_tainted */ true,
                                ))
                            },
                            AttributeType::RawString | AttributeType::None => {
                                simple_attr_subst(&attr)
                            },
                            AttributeType::Invalid => None,
                        }
                    },
                )
        },
    };

    if let Some(s) = substitution {
        return Ok(s);
    }

    let Some(ref fallback) = reference.fallback else {
        return Err(());
    };

    do_substitute_chunk(
        css,
        fallback.start.get(),
        reference.end - 1, // Skip the closing parenthesis of the reference value.
        fallback.first_token_type,
        fallback.last_token_type,
        url_data,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        &fallback.references.refs,
        attribute_tracker,
        seen,
        /* attr_taint */ None,
    )
}

impl<Component: PartialEq> PartialEq for Value<Component> {
    // Ignore the url_data and tainting fields when comparing values for equality.
    fn eq(&self, other: &Self) -> bool {
        self.v == other.v
    }
}

pub fn universal(var: Arc<ComputedPropertyValue>) -> Self {
    let attr_tainted = var.is_attr_tainted();
    let url_data = var.url_data.clone();
    let v = ValueInner::Universal(var);
    Self {
        v,
        url_data,
        attr_tainted,
    }
}

pub fn to_declared_value(&self) -> properties::CustomDeclarationValue {
    if let ValueInner::Universal(ref var) = self.v {
        // The attr()-taint of the wrapper must survive the round-trip through the declared
        // value, otherwise re-cascading the reference-free inner value
        // would launder the taint and allow attribute-derived URLs to be fetched.
        // This is necessary because we currently reimplement the cascade for animations in
        // Servo_GetComputedKeyframeValues. We should instead just use the 'normal' path for
        // animated values. For more information see Bug 1883255.
        // https://drafts.csswg.org/css-values-5/#attr-security
        if self.attr_tainted && !var.is_attr_tainted() {
            let mut tainted = (**var).clone();
            tainted.explicitly_attr_tainted = true;
            return properties::CustomDeclarationValue::Unparsed(Arc::new(tainted));
        }
        return properties::CustomDeclarationValue::Unparsed(Arc::clone(var));
    }
    properties::CustomDeclarationValue::Parsed(Arc::new(ToComputedValue::from_computed_value(
        self,
    )))
}

pub fn disallow_urls_in_range(&self, range: &AttrTaintedRange) -> bool {
    self.attr_tainted_regions
        .should_disallow_urls_in_range(range)
}

pub fn parse_from_string(
    url: String,
    url_start: usize,
    url_end: usize,
    context: &ParserContext,
    cors_mode: CorsMode,
) -> Result<Self, ParseError> {
    use crate::custom_properties::AttrTaintedRange;
    use style_traits::StyleParseErrorKind;
    let range = AttrTaintedRange::new(url_start, url_end);
    if context.disallow_urls_in_range(&range) {
        return Err(ParseError::custom(StyleParseErrorKind::UnspecifiedError));
    }
    Ok(Self::new_from_string(url, context, cors_mode))
}

fn parse(
    context: &ParserContext,
    input: &mut Parser,
    cors_mode: CorsMode,
    flags: ParseImageFlags,
) -> Result<Self, ParseError> {
    let start = input.position().byte_index();
    let image = match input.try_parse(|i| i.expect_url_or_string()) {
        Ok(url) => {
            let end = input.position().byte_index();
            Image::Url(SpecifiedUrl::parse_from_string(
                url.as_ref().into(),
                start,
                end,
                context,
                cors_mode,
            )?)
        },
        Err(..) => Image::parse_with_cors_mode(
            context,
            input,
            cors_mode,
            flags | ParseImageFlags::FORBID_NONE | ParseImageFlags::FORBID_IMAGE_SET,
        )?,
    };

    let mut resolution = input
        .try_parse(|input| Resolution::parse(context, input))
        .ok();
    let mime_type = input.try_parse(Self::parse_type).ok();

    // Try to parse resolution after type().
    if mime_type.is_some() && resolution.is_none() {
        resolution = input
            .try_parse(|input| Resolution::parse(context, input))
            .ok();
    }

    let resolution = resolution.unwrap_or_else(|| Resolution::from_x(1.0));
    let has_mime_type = mime_type.is_some();
    let mime_type = mime_type.unwrap_or_default();

    Ok(Self {
        image,
        resolution,
        has_mime_type,
        mime_type,
    })
}

fn can_deduplicate_values(
    a: Option<&ComputedRegisteredValue>,
    b: Option<&ComputedRegisteredValue>,
) -> bool {
    match (a, b) {
        (Some(a), Some(b)) => {
            // TODO(emilio): Seems we should compare `url_data` as well? It doesn't seem to matter
            // much in practice since url values would be already-computed against the right base
            // URI here, I think...
            a == b && a.attr_tainted == b.attr_tainted
        },
        (None, None) => true,
        _ => false,
    }
}

fn do_insert(&mut self, name: &Name, value: Option<ComputedRegisteredValue>) {
    if let Some(inner) = Arc::get_mut(&mut self.0) {
        return inner.insert(name, value);
    }
    if can_deduplicate_values(self.get(name), value.as_ref()) {
        return;
    }
    if !self.0.should_expand_chain() {
        return Arc::make_mut(&mut self.0).insert(name, value);
    }
    let len = self.0.len;
    let ancestor_count = self.0.ancestor_count + 1;
    let mut new_inner = Inner {
        own_properties: Default::default(),
        // FIXME: Would be nice to avoid this clone.
        parent: Some(self.0.clone()),
        len,
        ancestor_count,
    };
    new_inner.insert(name, value);
    self.0 = Arc::new(new_inner);
}

fn value_may_affect_style(
    context: &computed::Context,
    name: &Name,
    registration: &PropertyDescriptors,
    initial_values: &ComputedCustomProperties,
    value: &CustomDeclarationValue,
) -> bool {
    match *value {
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Inherit) => {
            // For inherited custom properties, explicit 'inherit' means we
            // can just use any existing value in the inherited
            // CustomPropertiesMap.
            if registration.inherits() {
                return false;
            }
        },
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Initial) => {
            // For non-inherited custom properties, explicit 'initial' means
            // we can just use any initial value in the registration.
            if !registration.inherits() {
                return false;
            }
        },
        CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Unset) => {
            // Explicit 'unset' means we can either just use any existing
            // value in the inherited CustomPropertiesMap or the initial
            // value in the registration.
            return false;
        },
        _ => {},
    }

    let existing_value = context
        .builder
        .substitution_functions
        .get_var(registration, name);
    let Some(existing_value) = existing_value else {
        if matches!(
            value,
            CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Initial)
        ) {
            debug_assert!(registration.inherits(), "Should've been handled earlier");
            // The initial value of a custom property without a
            // guaranteed-invalid initial value is the same as it
            // not existing in the map.
            if registration.initial_value.is_none() {
                return false;
            }
        }
        return true;
    };
    match value {
        CustomDeclarationValue::Unparsed(value) => {
            // Don't bother overwriting an existing value with the same
            // specified value.
            if let Some(existing_unparsed) = existing_value.as_universal() {
                return existing_value.attr_tainted != value.is_attr_tainted()
                    || existing_unparsed != value;
            }
        },
        CustomDeclarationValue::Parsed(..) => {
            // If the value has dependencies, context might not yield the same
            // result as the eventual value.
        },
        CustomDeclarationValue::CSSWideKeyword(kw) => {
            match kw {
                CSSWideKeyword::Inherit => {
                    debug_assert!(!registration.inherits(), "Should've been handled earlier");
                    // Root inheritance uses the already-seeded initial value.
                    if context.is_root_element() {
                        return false;
                    }
                },
                CSSWideKeyword::Initial => {
                    debug_assert!(registration.inherits(), "Should've been handled earlier");
                    // Don't bother overwriting an existing value with the initial value
                    // specified in the registration.
                    if let Some(initial_value) = initial_values.get(registration, name) {
                        return existing_value.attr_tainted || existing_value != initial_value;
                    }
                },
                CSSWideKeyword::Unset => {
                    debug_assert!(false, "Should've been handled earlier");
                },
                CSSWideKeyword::Revert
                | CSSWideKeyword::RevertLayer
                | CSSWideKeyword::RevertRule => {},
            }
        },
    };

    true
}

pub fn should_disallow_urls_in_range(&self, range: &AttrTaintedRange) -> bool {
    self.0
        .iter()
        .any(|r| r.start <= range.end && r.end >= range.start)
}
